import{_ as o,I as n,c as i,o as s,ag as r,J as a}from"./chunks/framework.ARG558ZT.js";const y=JSON.parse('{"title":"Whole-hub roadmap and why it is grouped this way","description":"","frontmatter":{},"headers":[],"relativePath":"learner-guide/roadmap.md","filePath":"learner-guide/roadmap.md"}'),d={name:"learner-guide/roadmap.md"};function c(l,e,h,u,p,m){const t=n("MermaidDiagram");return s(),i("div",null,[e[0]||(e[0]=r('<h1 id="whole-hub-roadmap-and-why-it-is-grouped-this-way" tabindex="-1">Whole-hub roadmap and why it is grouped this way <a class="header-anchor" href="#whole-hub-roadmap-and-why-it-is-grouped-this-way" aria-label="Permalink to “Whole-hub roadmap and why it is grouped this way”">​</a></h1><p><a href="./">Guide home</a> · <a href="./tracks.html">Track sequences</a> · <a href="./topics.html">Every topic</a></p><h2 id="a-readable-journey" tabindex="-1">A readable journey <a class="header-anchor" href="#a-readable-journey" aria-label="Permalink to “A readable journey”">​</a></h2><p>Begin with a programming and ownership foundation: JavaScript values, scope, collections, promises, modules and error handling. Add basic terminal/Git habits and the ability to state an input/output contract. For your current goal, go straight into Node&#39;s bounded analyzer. HTML/CSS/accessibility is essential for the browser branch, rather than a gate for all programming.</p><p>From there, study CS reasoning in parallel: costs, invariants and representations make stream counters, queues and concurrency limits easier to defend. Grow one browser document through typed UI and React only when you want an interface. Grow one Node program through HTTP, validation, SQL transactions and authorization only when you want a backend. Integrate these at an actual UI/API contract, rather than assuming shared types enforce runtime authority.</p><p>After a working service, learn lifecycle, observability, failure recovery, distribution and artifact/schema compatibility. Begin locally; hosted deployment requires its own actual evidence. Python is another implementation route for typed, bounded data preparation, then model/evaluation/security foundations, RAG and controlled tool workflows. n8n is an integration/orchestration branch after JSON/HTTP and service authority; it is not a substitute for those boundaries.</p><p>Engineering practice accompanies all of these: testing early, security at trust boundaries, state ownership when sharing data, performance measurement once a real flow exists, and architecture/release decisions once there is something concrete to operate. Specialist frameworks are optional after a relevant primary path.</p><h2 id="prerequisite-relationships" tabindex="-1">Prerequisite relationships <a class="header-anchor" href="#prerequisite-relationships" aria-label="Permalink to “Prerequisite relationships”">​</a></h2><p>Solid arrows mean required capability for <strong>the shown implementation milestone</strong>, not a requirement to finish every chapter. Dashed arrows marked background are helpful; dashed optional branches are choices. These are this guide&#39;s synthesis of the existing prerequisite statements.</p>',9)),a(t,{"encoded-source":"flowchart%20TD%0A%20JS%5BJavaScript%20basics%5D%20--%3E%20N%5BNode%20N-01%20to%20N-06%5D%0A%20JS%20--%3E%20CS%5BCS%20reasoning%20and%20structures%5D%0A%20HTML%5BHTML%20CSS%20accessibility%5D%20--%3E%20F%5BFrontend%20F01%20to%20F04%5D%0A%20JS%20--%3E%20F%0A%20F%20--%3E%20R%5BReact%20F05%5D%0A%20N%20--%3E%20API%5BHTTP%20Express%20SQL%20authorization%20P-331%5D%0A%20R%20--%3E%20NX%5BNext%20F06%20with%20server%20authority%5D%0A%20API%20--%3E%20NX%0A%20API%20--%3E%20OPS%5BRecovery%20and%20deployment%20P-333%5D%0A%20N%20--%3E%20FAIL%5BRuntime%20failure%20lab%20P-332%5D%0A%20CS%20-.%20background%20.-%3E%20FAIL%0A%20CS%20-.%20background%20.-%3E%20API%0A%20API%20-.%20optional%20need%20.-%3E%20ALT%5BMongoDB%20Redis%20GraphQL%20transports%5D%0A%20OPS%20-.%20optional%20platform%20.-%3E%20CLOUD%5BAWS%20Kubernetes%20awareness%5D"}),a(t,{"encoded-source":"flowchart%20TD%0A%20PY%5BTyped%20Python%20and%20bounded%20async%20I%2FO%5D%20--%3E%20SH%5BShared%20schemas%20tools%20security%20budgets%20evaluation%5D%0A%20SH%20--%3E%20RAG%5BP-334%20RAG-1%20to%20RAG-4%5D%0A%20SH%20--%3E%20WF%5BP-335%20WF-1%20to%20WF-4%5D%0A%20HTTP%5BJSON%20HTTP%20and%20scoped%20service%20identity%5D%20--%3E%20N8%5BN8N-P01%20N-1%20to%20N-4%5D%0A%20SH%20-.%20background%20.-%3E%20N8%0A%20RAG%20-.%20optional%20evidence%20source%20.-%3E%20WF%0A%20PY%20--%3E%20COMP%5BP-337%20companion%20service%5D%0A%20SH%20-.%20optional%20protocol%20.-%3E%20MCP%5BMCP%20primitives%20connections%20security%20lifecycle%5D%0A%20SH%20-.%20optional%20specialization%20.-%3E%20EXT%5BModels%20modalities%20graphs%20adaptation%20ETL%20UI%5D"}),e[1]||(e[1]=r('<p>For a larger view, open the real rendered captures: <a href="/learner-guide/screenshots/10-prerequisites.png">runtime/browser prerequisite diagram</a> and <a href="/learner-guide/screenshots/11-prerequisites.png">Python/AI prerequisite diagram</a>. Narrow screens shrink the diagrams; use the full-size images with your browser image zoom, or follow the adjacent prose and track tables.</p><p>RAG is the recommended reading sequence before workflows in the hub, but a fixed authorized tool workflow need not implement a retrieval engine. n8n can start with deterministic item transformations before service integration. A Python service can begin with pure functions before deployment reading.</p><h2 id="repository-rationale-versus-recommendation" tabindex="-1">Repository rationale versus recommendation <a class="header-anchor" href="#repository-rationale-versus-recommendation" aria-label="Permalink to “Repository rationale versus recommendation”">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Rationale visible in current sources</th><th>Recommendation in this guide</th></tr></thead><tbody><tr><td>Frontend</td><td>Browser DOM, focus, layout, forms and state have distinct host responsibilities; coverage map assigns canonical lessons</td><td>Build one document → enhancement → typed UI → React → Next; defer optional stores until ownership needs them</td></tr><tr><td>Node</td><td>Runtime first; backend, persistence and delivery are explicit continuations</td><td>N-01–06 now, P-332 next, P-331 when service work is useful</td></tr><tr><td>CS</td><td>Correctness, cost and representation are independent of frameworks</td><td>Pair selected reasoning with analyzer bottlenecks; do not delay Node for the entire course</td></tr><tr><td>Applied AI / Python</td><td>Detailed URLs remain in Python; grouped homes separate evidence selection, actions and automation</td><td>Follow concepts across folders rather than treating forty Python files as forty consecutive prerequisites</td></tr><tr><td>Engineering</td><td>State, measured performance, security, quality, delivery and design reuse P-328–337</td><td>Add each control at the boundary it protects, then use E01–E07 to deepen the same product</td></tr><tr><td>AI-assisted engineering</td><td>Issue → local diff → checks → traceability; distinct from autonomous product workflows</td><td>Start P-336 with a small real/study issue once you can explain its contract</td></tr><tr><td>Senior Growth</td><td>Interview-origin subject collections retained behind canonical paths</td><td>Use as linked depth/reference; alphabetical folders are not another mandatory curriculum</td></tr></tbody></table><h2 id="menu-order-is-not-study-order" tabindex="-1">Menu order is not study order <a class="header-anchor" href="#menu-order-is-not-study-order" aria-label="Permalink to “Menu order is not study order”">​</a></h2><p>Learning paths lists Frontend, CS, Node, Applied AI, AI Engineering, Engineering. Your recommended start is Node. Node module numbers put testing before networking, MongoDB before PostgreSQL and diagnostics after production: the current Node reading guide instead prioritizes core runtime/testing/HTTP/diagnostics/lifecycle, with PostgreSQL the main persistence route. Shared backend project IDs put P-331 before P-332; smaller runtime practice is recommended first. Materials, assessment, technical checks and historical audit files are resources/records, not next chapters.</p><h2 id="keep-optional-scope-bounded" tabindex="-1">Keep optional scope bounded <a class="header-anchor" href="#keep-optional-scope-bounded" aria-label="Permalink to “Keep optional scope bounded”">​</a></h2><p>After the primary branch, choose at most one relevant comparison: Redux/alternative stores, advanced conditional types, custom widgets/virtualization, RxJS, workers/custom elements, microfrontends, alternative renderers or legacy jQuery/Flux; MongoDB/Redis/GraphQL/real-time transports; AWS/IaC/Kubernetes awareness; model theory/modalities, MCP, graph data/adaptation, ETL/Streamlit/cache/batch. Their exact local lessons and practice are retained in the mapping. External course catalogues provide links; their unseen content has not been certified as covered here.</p>',8))])}const b=o(d,[["render",c]]);export{y as __pageData,b as default};
